// types.ts
//
// Purpose: Shared types and constants for shiggy system

import { injectGlobalStyles } from "../../../shared/styles/inject";
import { Typography } from "../../ui/style-constants";

export const GIF_RESTART_MS = 11000;
export const AUTO_SPAWN_MS = 6000;
export const PET_SUMMON_THRESHOLD = 5;
export const AUTO_SPAWN_MILESTONE = 100;
export const SHIGGY_SIZE = 60;
export const SHIGGY_RADIUS = 28;
// Hitbox relative to sprite size for consistent collision across scales
export const SHIGGY_HITBOX_RADIUS = SHIGGY_SIZE * 0.3;
export const FOLLOW_UNLOCK_PETS = 5;
export const MAX_FOLLOWERS = 10;
export const PROXIMITY_PX = 200;
export const FOLLOW_PROXIMITY_PX = 80;
export const DWELL_TIME_MS = 2000;
export const MAX_FOLLOW_SPEED = 800;
export const UNFOLLOW_YANK_PX_S = 1800;
export const UNFOLLOW_BUFFER_MS = 800;
export const OFFSET_RADIUS = 80;

// Elastic rope physics
export const ROPE_SLACK = 60;
export const ROPE_K = 0.045;
export const ROPE_DAMPING = 0.978;
export const ROPE_AXIAL_DAMPING = 0.1;
export const MAX_VEL = Infinity;

// Collision
// Cursor collision radius relative to shiggy size for consistent feel
export const CURSOR_RADIUS = SHIGGY_SIZE * 0.25;
export const CURSOR_HOTSPOT_RADIUS = SHIGGY_SIZE * 0.4;
// Newtonian collision: momentum transfer based on mass ratio
// v_shiggy' = (m_cursor / (m_cursor + m_shiggy)) * (1 + e) * v_cursor_normal
// Heavier cursor = more momentum transfer to shiggy
export const CURSOR_MASS = 1.0;
export const SHIGGY_MASS = 2.0;
export const COLLISION_RESTITUTION = 0.5; // 0 = inelastic, 1 = elastic
// Computed momentum transfer coefficient
export const MOMENTUM_FACTOR =
	(CURSOR_MASS * (1 + COLLISION_RESTITUTION)) / (CURSOR_MASS + SHIGGY_MASS);

// NPC movement (slow hockey puck)
export const NPC_FRICTION = 0.99;
export const NPC_BOUNCE_ENERGY = 1.0;
export const NPC_IDLE_SPEED = 0.45;
export const NPC_WAYPOINT_DIST_MIN = 60;
export const NPC_WAYPOINT_MIN_MS = 3000;
export const NPC_WAYPOINT_RAND_MS = 3000;
export const NPC_IDLE_PAUSE_MIN_MS = 500;
export const NPC_IDLE_PAUSE_RAND_MS = 1500;
export const EXPLORE_CHANCE = 0.00015;
export const EXPLORE_DURATION_MS = 8000;
export const EXPLORE_MIN_FOLLOW_MS = 12000;

// Conversation
export const CONVO_PROXIMITY = 100;
export const CONVO_CHANCE = 0.002;

export interface SummonedShiggy {
	img: HTMLImageElement;
	gifTimer: ReturnType<typeof setInterval>;
	following: boolean;
	followingSince: number;
	exploring: boolean;
	exploreUntil: number;
	approaching: boolean;
	unfollowAt: number;
	targetX: number;
	targetY: number;
	x: number;
	y: number;
	vx: number;
	vy: number;
	smoothVx: number;
	smoothVy: number;
	offsetAngle: number;
	offsetDist: number;
	cursorBias: number;
	dialogue: HTMLDivElement | null;
	waypointX: number;
	waypointY: number;
	waypointTimer: number;
	inConversation: boolean;
	convoPartner: SummonedShiggy | null;
	convoTurn: number;
	convoTimer: ReturnType<typeof setTimeout> | null;
}

export interface MouseSample {
	x: number;
	y: number;
	t: number;
}

export function injectShiggyCss(): void {
	injectGlobalStyles(
		document,
		"shiggy",
		`
        @keyframes shiggy-float {
            0%, 100% { transform: translateY(0); }
            25% { transform: translateY(-8px); }
            75% { transform: translateY(-4px); }
        }
        @keyframes shiggy-summon-enter {
            0% { transform: scale(0) rotate(-20deg); opacity: 0; }
            60% { transform: scale(1.2) rotate(5deg); opacity: 1; }
            100% { transform: scale(1) rotate(0deg); opacity: 1; }
        }
        @keyframes shiggy-summon-exit {
            0% { transform: scale(1) rotate(0deg); opacity: 1; }
            40% { transform: scale(1.1) rotate(-10deg); opacity: 0.8; }
            100% { transform: scale(0) rotate(30deg); opacity: 0; }
        }
        @keyframes shiggy-convo-pop {
            0% { opacity: 0; transform: translateX(-50%) scale(0.7); }
            20% { opacity: 1; transform: translateX(-50%) scale(1.05); }
            35% { transform: translateX(-50%) scale(1); }
            80% { opacity: 1; }
            100% { opacity: 0; transform: translateX(-50%) translateY(-6px); }
        }
        .beepboxEditor .shiggy-img {
            width: 60px; height: auto; pointer-events: none; opacity: 0;
            transition: opacity 0.2s; cursor: pointer;
        }
        .beepboxEditor .shiggy-toggle {
            text-align: center; user-select: none; margin-top: 2px;
        }
        .beepboxEditor .shiggy-label {
            font-size: ${Typography.sizeSm}; color: var(--secondary-text); cursor: pointer;
        }
        .beepboxEditor .shiggy-pet-display {
            font-size: ${Typography.sizeXs}; color: var(--secondary-text);
            min-height: 1.2em; text-align: center; margin-top: 2px;
            word-wrap: break-word; overflow-wrap: break-word; white-space: normal;
        }
        .beepboxEditor .shiggy-counter {
            font-size: ${Typography.sizeXs}; color: var(--secondary-text);
            opacity: 0; transition: opacity 0.3s; min-height: 1.2em;
        }
        .beepboxEditor .shiggy-release-btn {
            font-size: ${Typography.sizeXs}; color: var(--secondary-text); cursor: pointer;
            opacity: 0; pointer-events: none;
            transition: opacity 0.3s, pointer-events 0s 0.3s; margin-top: 2px; user-select: none;
        }
    `,
	);
}
