import { HTML } from "imperative-html/dist/esm/elements-strict";
import type { Channel, Instrument } from "../../synth";
import { ChangeAppendInstrument, ChangePasteInstrument, ChangeViewInstrument } from "../changes";
import type { SongDocument } from "../song-document";
import { actionButton, selectField, setDisabled } from "../ui";
import {
	BasePrompt,
	createPromptSurface,
	type PromptRenderSurface,
	type PromptSurfaceOptions,
} from "./base-prompt";

const { div, input, output, select, option, code } = HTML;

export class InstrumentImportPrompt extends BasePrompt {
	private readonly _importStrategySelect: HTMLSelectElement = select(
		{},
		option({ value: "append" }, "Append instruments to the end of the list."),
		option({ value: "replace" }, "Replace only the selected instrument."),
		option({ value: "all" }, "Replace all instruments in the channel."),
	);
	private readonly _fileInput: HTMLInputElement = input({
		type: "file",
		accept: ".json,application/json",
	});
	private readonly _browseButton: HTMLButtonElement;
	private readonly _fileStatus: HTMLOutputElement = output(
		{
			class: "importFileStatus",
			"aria-label": "Selected instrument file",
			"aria-live": "polite",
		},
		"No file selected.",
	);

	private readonly _strategyInfoText: HTMLDivElement = div(
		{},
		"You must enable either ",
		code("Simultaneous instruments per channel"),
		" or ",
		code("Different instruments per pattern"),
		" to change the import strategy.",
	);

	private readonly _surface: PromptRenderSurface;
	private _operation = 0;
	private _disposed = false;
	private _activeReader: FileReader | null = null;

	public readonly container: HTMLElement;

	constructor(doc: SongDocument, options: PromptSurfaceOptions = {}) {
		super(doc);
		this._surface = options.surface ?? "standalone";
		this._browseButton = actionButton("Browse\u2026", {
			class: "importBrowseButton",
			type: "button",
			...(this._surface === "navigator" ? { surface: "secondary" as const } : {}),
		});
		if (this._surface === "navigator") this._fileInput.style.display = "none";
		const children: Node[] =
			this._surface === "standalone"
				? [
						this._strategyInfoText,
						selectField("Import:", this._importStrategySelect),
						this._fileInput,
						this._cancelButton,
					]
				: [
						this._strategyInfoText,
						selectField("Import strategy:", this._importStrategySelect),
						div({ class: "importFileRow" }, this._browseButton, this._fileStatus),
						this._fileInput,
					];
		this.container = createPromptSurface(
			this._surface,
			this._surface === "navigator"
				? "instrumentImportPrompt importPrompt"
				: "instrumentImportPrompt",
			"Import Instrument(s)",
			"import",
			...children,
		);
		if (this._surface === "standalone") this.buildTitlebar();
		if (!(doc.song.patternInstruments || doc.song.layeredInstruments)) {
			setDisabled(this._importStrategySelect, true);
			this._importStrategySelect.value = "replace";
			this._strategyInfoText.hidden = false;
		} else {
			const lastStrategy: string | null = window.localStorage.getItem(
				"instrumentImportStrategy",
			);
			if (lastStrategy != null) this._importStrategySelect.value = lastStrategy;
			this._strategyInfoText.hidden = true;
		}
		this._browseButton.addEventListener("click", this._whenBrowseClicked);
		this._fileInput.addEventListener("change", this._whenFileSelected);
	}

	public override cleanUp(): void {
		this._disposed = true;
		this._operation++;
		this._activeReader?.abort();
		this._activeReader = null;
		super.cleanUp();
		this._browseButton.removeEventListener("click", this._whenBrowseClicked);
		this._fileInput.removeEventListener("change", this._whenFileSelected);
	}

	private _whenBrowseClicked = (): void => {
		this._fileInput.click();
	};

	private _whenFileSelected = (): void => {
		const file: File | undefined = this._fileInput.files?.[0];
		if (!file) {
			this._fileStatus.textContent = "No file selected.";
			return;
		}
		this._fileStatus.textContent = file.name;
		this._activeReader?.abort();
		const operation = ++this._operation;
		const reader: FileReader = new FileReader();
		this._activeReader = reader;
		reader.onload = (e) => {
			if (this._disposed || operation !== this._operation) return;
			this._activeReader = null;
			try {
				const fileParsed: any = JSON.parse(String(e.target?.result));
				if (Array.isArray(fileParsed)) {
					if (!(this._doc.song.patternInstruments || this._doc.song.layeredInstruments)) {
						alert(
							"Instrument file contains multiple instruments! Please turn on either Simultaneous instruments per channel or Different instruments per pattern!",
						);
						return;
					}
					this._import_multiple(fileParsed);
				} else {
					this._import_single(fileParsed);
				}
			} catch (error) {
				console.error("Error reading file:", error);
			}
		};
		reader.readAsText(file);
	};

	private _import_multiple = (file: any[]): void => {
		const channel: Channel = this._doc.song.channels[this._doc.channel];
		const currentInstrum: Instrument = channel.instruments[this._doc.getCurrentInstrument()];
		window.localStorage.setItem("instrumentImportStrategy", this._importStrategySelect.value);
		let replacementIndex = 1;

		switch (this._importStrategySelect.value) {
			case "replace":
				this._doc.record(new ChangePasteInstrument(this._doc, currentInstrum, file[0]));
				while (replacementIndex < file.length) {
					if (!this._validate_instrument_limit(channel)) {
						alert("Max instruments reached! Some instruments were not imported.");
						break;
					}
					this._doc.record(
						new ChangeAppendInstrument(this._doc, channel, file[replacementIndex]),
					);
					replacementIndex++;
				}
				break;
			case "all":
				channel.instruments.length = 0;
				for (const insturm of file) {
					if (!this._validate_instrument_limit(channel)) {
						alert("Max instruments reached! Some instruments were not imported.");
						break;
					}
					this._doc.record(new ChangeAppendInstrument(this._doc, channel, insturm));
				}
				break;
			default:
				for (const insturm of file) {
					if (!this._validate_instrument_limit(channel)) {
						alert("Max instruments reached! Some instruments were not imported.");
						break;
					}
					this._doc.record(new ChangeAppendInstrument(this._doc, channel, insturm));
				}
				break;
		}
		this._doc.record(
			new ChangeViewInstrument(
				this._doc,
				this._importStrategySelect.value === "all"
					? channel.instruments.length - 1
					: this._doc.getCurrentInstrument(),
			),
		);
		this._doc.notifier.changed();
		this._close();
	};

	private _validate_instrument_limit = (channel: Channel): boolean => {
		return this._doc.song.getMaxInstrumentsPerChannel() > channel.instruments.length;
	};

	private _import_single = (file: any): void => {
		const channel: Channel = this._doc.song.channels[this._doc.channel];
		const currentInstrum: Instrument = channel.instruments[this._doc.getCurrentInstrument()];
		window.localStorage.setItem("instrumentImportStrategy", this._importStrategySelect.value);

		switch (this._importStrategySelect.value) {
			case "replace":
				this._doc.record(new ChangePasteInstrument(this._doc, currentInstrum, file));
				break;
			case "all":
				channel.instruments.length = 1;
				this._doc.record(
					new ChangePasteInstrument(this._doc, channel.instruments[0], file),
				);
				this._doc.record(new ChangeViewInstrument(this._doc, 0));
				break;
			default:
				if (!this._validate_instrument_limit(channel)) {
					alert("Max instruments reached! The instrument was not imported.");
				} else {
					this._doc.record(new ChangeAppendInstrument(this._doc, channel, file));
					this._doc.record(
						new ChangeViewInstrument(this._doc, channel.instruments.length - 1),
					);
				}
				break;
		}
		this._doc.notifier.changed();
		this._close();
	};

	protected override _saveChanges(): void {
		this._close();
	}
}
