export class SpectrumEditor {
	private readonly _editorWidth: number = 120;
	private readonly _editorHeight: number = 26;
	private readonly _fill: SVGPathElement = SVG.path({
		fill: ColorConfig.uiWidgetBackground,
		"pointer-events": "none",
	});
	private readonly _octaves: SVGSVGElement = SVG.svg({ "pointer-events": "none" });
	private readonly _fifths: SVGSVGElement = SVG.svg({ "pointer-events": "none" });
	private readonly _curve: SVGPathElement = SVG.path({
		fill: "none",
		stroke: "currentColor",
		"stroke-width": 2,
		"pointer-events": "none",
	});
	private readonly _arrow: SVGPathElement = SVG.path({
		fill: "currentColor",
		"pointer-events": "none",
	});
	private readonly _svg: SVGSVGElement = SVG.svg(
		{
			style: `background-color: ${ColorConfig.editorBackground}; touch-action: none; cursor: crosshair;`,
			width: "100%",
			height: "100%",
			viewBox: `0 0 ${this._editorWidth} ${this._editorHeight}`,
			preserveAspectRatio: "none",
		},
		this._fill,
		this._octaves,
		this._fifths,
		this._curve,
		this._arrow,
	);

	public readonly container: HTMLElement = HTML.div(
		{ class: "spectrum", style: "height: 100%;" },
		this._svg,
	);

	private _mouseX: number = 0;
	private _mouseY: number = 0;
	private _freqPrev: number = 0;
	private _ampPrev: number = 0;
	private _mouseDown: boolean = false;
	private _change: ChangeSpectrum | null = null;
	private _renderedPath: string = "";
	private _renderedFifths: boolean = true;
	private _svgRect: DOMRect | null = null;
	private instrument: Instrument;
	// private _initial: SpectrumWave = new SpectrumWave(this._spectrumIndex != null);

	private _undoHistoryState: number = 0;
	private _changeQueue: number[][] = [];
	private readonly _initialSpectrum: number[];

	private _doc: SongDocument;

	constructor(
		_doc: SongDocument,
		private _spectrumIndex: number | null,
		private _isPrompt: boolean = false,
	) {
		this._doc = _doc;
		this.instrument = this._doc.getCurrentInstrumentObj();
		this._initialSpectrum = this.getSpectrumWave().spectrum.slice();
		// this._initial.spectrum = this._spectrumIndex == null ? this.instrument.spectrumWave.spectrum.slice() : this.instrument.drumsetSpectrumWaves[this._spectrumIndex].spectrum.slice();
		for (
			let i: number = 0;
			i < Config.spectrumControlPoints;
			i += Config.spectrumControlPointsPerOctave
		) {
			this._octaves.appendChild(
				SVG.rect({
					fill: ColorConfig.tonic,
					x: ((i + 1) * this._editorWidth) / (Config.spectrumControlPoints + 2) - 1,
					y: 0,
					width: 2,
					height: this._editorHeight,
				}),
			);
		}
		for (
			let i: number = 4;
			i <= Config.spectrumControlPoints;
			i += Config.spectrumControlPointsPerOctave
		) {
			this._fifths.appendChild(
				SVG.rect({
					fill: ColorConfig.fifthNote,
					x: ((i + 1) * this._editorWidth) / (Config.spectrumControlPoints + 2) - 1,
					y: 0,
					width: 2,
					height: this._editorHeight,
				}),
			);
		}

		this.storeChange();

		this.container.addEventListener("mousedown", this._whenMousePressed);
		document.addEventListener("mousemove", this._whenMouseMoved);
		document.addEventListener("mouseup", this._whenCursorReleased);
		window.addEventListener("resize", () => (this._svgRect = null));
		window.addEventListener("scroll", () => (this._svgRect = null), {
			capture: true,
			passive: true,
		});

		this.container.addEventListener("touchstart", this._whenTouchPressed);
		this.container.addEventListener("touchmove", this._whenTouchMoved);
		this.container.addEventListener("touchend", this._whenCursorReleased);
		this.container.addEventListener("touchcancel", this._whenCursorReleased);
	}

	public storeChange = (): void => {
		// Check if change is unique compared to the current history state
		let sameCheck = true;
		if (this._changeQueue.length > 0) {
			for (let i = 0; i < Config.spectrumControlPoints; i++) {
				if (
					this._changeQueue[this._undoHistoryState][i] !==
					this.instrument.spectrumWave.spectrum[i]
				) {
					sameCheck = false;
					i = Config.spectrumControlPoints;
				}
			}
		}

		if (!sameCheck || this._changeQueue.length === 0) {
			// Create new branch in history, removing all after this in time
			this._changeQueue.splice(0, this._undoHistoryState);

			this._undoHistoryState = 0;

			this._changeQueue.unshift(this.instrument.spectrumWave.spectrum.slice());

			// 32 undo max
			if (this._changeQueue.length > 32) {
				this._changeQueue.pop();
			}
		}
	};

	public undo = (): void => {
		// Go backward, if there is a change to go back to
		if (this._undoHistoryState < this._changeQueue.length - 1) {
			this._undoHistoryState++;
			const spectrum: number[] = this._changeQueue[this._undoHistoryState].slice();
			this.setSpectrumWave(spectrum);
		}
	};

	public redo = (): void => {
		// Go forward, if there is a change to go to
		if (this._undoHistoryState > 0) {
			this._undoHistoryState--;
			const spectrum: number[] = this._changeQueue[this._undoHistoryState].slice();
			this.setSpectrumWave(spectrum);
		}
	};

	private _xToFreq(x: number): number {
		return ((Config.spectrumControlPoints + 2) * x) / this._editorWidth - 1;
	}

	private _yToAmp(y: number): number {
		return Config.spectrumMax * (1 - (y - 1) / (this._editorHeight - 2));
	}

	private _whenMousePressed = (event: MouseEvent): void => {
		event.preventDefault();
		this._mouseDown = true;
		this._svgRect = this._svg.getBoundingClientRect();
		const boundingRect: DOMRect = this._svgRect;
		this._mouseX =
			(((event.clientX || event.pageX) - boundingRect.left) * this._editorWidth) /
			(boundingRect.right - boundingRect.left);
		this._mouseY =
			(((event.clientY || event.pageY) - boundingRect.top) * this._editorHeight) /
			(boundingRect.bottom - boundingRect.top);
		if (Number.isNaN(this._mouseX)) this._mouseX = 0;
		if (Number.isNaN(this._mouseY)) this._mouseY = 0;

		this._freqPrev = this._xToFreq(this._mouseX);
		this._ampPrev = this._yToAmp(this._mouseY);
		this._whenCursorMoved();
	};

	private _whenTouchPressed = (event: TouchEvent): void => {
		event.preventDefault();
		this._mouseDown = true;
		this._svgRect = this._svg.getBoundingClientRect();
		const boundingRect: DOMRect = this._svgRect;
		this._mouseX =
			((event.touches[0].clientX - boundingRect.left) * this._editorWidth) /
			(boundingRect.right - boundingRect.left);
		this._mouseY =
			((event.touches[0].clientY - boundingRect.top) * this._editorHeight) /
			(boundingRect.bottom - boundingRect.top);
		if (Number.isNaN(this._mouseX)) this._mouseX = 0;
		if (Number.isNaN(this._mouseY)) this._mouseY = 0;

		this._freqPrev = this._xToFreq(this._mouseX);
		this._ampPrev = this._yToAmp(this._mouseY);
		this._whenCursorMoved();
	};

	private _whenMouseMoved = (event: MouseEvent): void => {
		if (this.container.offsetParent == null) return;
		if (!this._svgRect) this._svgRect = this._svg.getBoundingClientRect();
		const boundingRect = this._svgRect;
		this._mouseX =
			(((event.clientX || event.pageX) - boundingRect.left) * this._editorWidth) /
			(boundingRect.right - boundingRect.left);
		this._mouseY =
			(((event.clientY || event.pageY) - boundingRect.top) * this._editorHeight) /
			(boundingRect.bottom - boundingRect.top);
		if (Number.isNaN(this._mouseX)) this._mouseX = 0;
		if (Number.isNaN(this._mouseY)) this._mouseY = 0;
		this._whenCursorMoved();
	};

	private _whenTouchMoved = (event: TouchEvent): void => {
		if (this.container.offsetParent == null) return;
		if (!this._mouseDown) return;
		event.preventDefault();
		if (!this._svgRect) this._svgRect = this._svg.getBoundingClientRect();
		const boundingRect: DOMRect = this._svgRect;
		this._mouseX =
			((event.touches[0].clientX - boundingRect.left) * this._editorWidth) /
			(boundingRect.right - boundingRect.left);
		this._mouseY =
			((event.touches[0].clientY - boundingRect.top) * this._editorHeight) /
			(boundingRect.bottom - boundingRect.top);
		if (Number.isNaN(this._mouseX)) this._mouseX = 0;
		if (Number.isNaN(this._mouseY)) this._mouseY = 0;
		this._whenCursorMoved();
		this.render();
	};

	private _whenCursorMoved(): void {
		if (this._mouseDown) {
			const freq: number = this._xToFreq(this._mouseX);
			const amp: number = this._yToAmp(this._mouseY);

			const instrument: Instrument = this._doc.getCurrentInstrumentObj();
			const spectrumWave: SpectrumWave =
				this._spectrumIndex == null
					? instrument.spectrumWave
					: instrument.drumsetSpectrumWaves[this._spectrumIndex];

			if (freq !== this._freqPrev) {
				const slope: number = (amp - this._ampPrev) / (freq - this._freqPrev);
				const offset: number = this._ampPrev - this._freqPrev * slope;
				const lowerFreq: number = Math.ceil(Math.min(this._freqPrev, freq));
				const upperFreq: number = Math.floor(Math.max(this._freqPrev, freq));
				for (let i: number = lowerFreq; i <= upperFreq; i++) {
					if (i < 0 || i >= Config.spectrumControlPoints) continue;
					spectrumWave.spectrum[i] = Math.max(
						0,
						Math.min(Config.spectrumMax, Math.round(i * slope + offset)),
					);
				}
			}

			spectrumWave.spectrum[
				Math.max(0, Math.min(Config.spectrumControlPoints - 1, Math.round(freq)))
			] = Math.max(0, Math.min(Config.spectrumMax, Math.round(amp)));

			this._freqPrev = freq;
			this._ampPrev = amp;

			this._change = new ChangeSpectrum(this._doc, instrument, spectrumWave);
			this._doc.setProspectiveChange(this._change);
		}
	}

	private _whenCursorReleased = (_event: Event): void => {
		this._svgRect = null;
		if (this._mouseDown) {
			if (!this._isPrompt) {
				this._doc.record(this._change!);
			}
			this.storeChange();
			this._change = null;
		}
		this._mouseDown = false;
	};

	public getSpectrumWave(): SpectrumWave {
		const instrument: Instrument = this._doc.getCurrentInstrumentObj();
		if (this._spectrumIndex == null) {
			return instrument.spectrumWave;
		} else {
			return instrument.drumsetSpectrumWaves[this._spectrumIndex];
		}
	}

	public setSpectrumWave(spectrum: number[], saveHistory: boolean = false) {
		const instrument: Instrument = this._doc.getCurrentInstrumentObj();
		if (this._spectrumIndex == null) {
			for (let i = 0; i < Config.spectrumControlPoints; i++) {
				instrument.spectrumWave.spectrum[i] = spectrum[i];
			}
			const spectrumChange: ChangeSpectrum = new ChangeSpectrum(
				this._doc,
				instrument,
				instrument.spectrumWave,
			);
			if (saveHistory) {
				this._doc.record(spectrumChange);
			}
		} else {
			for (let i = 0; i < Config.spectrumControlPoints; i++) {
				instrument.drumsetSpectrumWaves[this._spectrumIndex].spectrum[i] = spectrum[i];
			}
			const spectrumChange: ChangeSpectrum = new ChangeSpectrum(
				this._doc,
				instrument,
				instrument.drumsetSpectrumWaves[this._spectrumIndex],
			);
			if (saveHistory) {
				this._doc.record(spectrumChange);
			}
		}
		this.render();
	}

	public saveSettings(): ChangeSpectrum {
		const instrument: Instrument = this._doc.getCurrentInstrumentObj();
		if (this._spectrumIndex == null || this._spectrumIndex === undefined) {
			return new ChangeSpectrum(this._doc, instrument, instrument.spectrumWave);
		} else {
			return new ChangeSpectrum(
				this._doc,
				instrument,
				instrument.drumsetSpectrumWaves[this._spectrumIndex],
			);
		}
	}

	public resetToInitial(): void {
		this.setSpectrumWave(this._initialSpectrum);
		this._changeQueue = [];
		this._undoHistoryState = 0;
	}

	public render(): void {
		const instrument: Instrument = this._doc.getCurrentInstrumentObj();
		const spectrumWave: SpectrumWave =
			this._spectrumIndex == null
				? instrument.spectrumWave
				: instrument.drumsetSpectrumWaves[this._spectrumIndex];
		const controlPointToHeight = (point: number): number => {
			return (1 - point / Config.spectrumMax) * (this._editorHeight - 1) + 1;
		};

		let lastValue: number = 0;
		let path: string = `M 0 ${prettyNumber(this._editorHeight)} `;
		for (let i: number = 0; i < Config.spectrumControlPoints; i++) {
			const nextValue: number = spectrumWave.spectrum[i];
			if (lastValue !== 0 || nextValue !== 0) {
				path += "L ";
			} else {
				path += "M ";
			}
			path += `${prettyNumber(((i + 1) * this._editorWidth) / (Config.spectrumControlPoints + 2))} ${prettyNumber(controlPointToHeight(nextValue))} `;
			lastValue = nextValue;
		}

		const lastHeight: number = controlPointToHeight(lastValue);
		if (lastValue > 0) {
			path += `L ${this._editorWidth - 1} ${prettyNumber(lastHeight)} `;
		}

		if (this._renderedPath !== path) {
			this._renderedPath = path;
			this._curve.setAttribute("d", path);
			this._fill.setAttribute(
				"d",
				path +
					"L " +
					this._editorWidth +
					" " +
					prettyNumber(lastHeight) +
					" L " +
					this._editorWidth +
					" " +
					prettyNumber(this._editorHeight) +
					" L 0 " +
					prettyNumber(this._editorHeight) +
					" z ",
			);

			this._arrow.setAttribute(
				"d",
				"M " +
					this._editorWidth +
					" " +
					prettyNumber(lastHeight) +
					" L " +
					(this._editorWidth - 4) +
					" " +
					prettyNumber(lastHeight - 4) +
					" L " +
					(this._editorWidth - 4) +
					" " +
					prettyNumber(lastHeight + 4) +
					" z",
			);
			this._arrow.style.display = lastValue > 0 ? "" : "none";
		}
		if (this._renderedFifths !== this._doc.prefs.showFifth) {
			this._renderedFifths = this._doc.prefs.showFifth;
			this._fifths.style.display = this._doc.prefs.showFifth ? "" : "none";
		}
	}

	// public reassignDoc(_doc: SongDocument) {
	//     this._doc = _doc;
	// }
}

export class SpectrumEditorPrompt implements Prompt {
	private static _nextId: number = 0;
	public readonly id: number = SpectrumEditorPrompt._nextId++;
	public closeCallback: ((prompt: Prompt) => void) | undefined = undefined;
	public spectrumEditor: SpectrumEditor = new SpectrumEditor(this._doc, null, true);

	private readonly spectrumEditors: SpectrumEditor[] = [];

	private _drumsetSpectrumIndex: number = 0;

	public readonly _playButton: HTMLButtonElement = HTML.button({
		style: "width: 55%;",
		type: "button",
	});

	public readonly _drumsetButtons: HTMLButtonElement[] = [];
	public readonly _drumsetButtonContainer: HTMLDivElement = HTML.div({
		class: "instrument-bar",
		style: "justify-content: center;",
	});

	private readonly _cancelButton: HTMLButtonElement = HTML.button({ class: "cancelButton" });
	private readonly _okayButton: HTMLButtonElement = actionButton("Commit");

	private readonly copyButton: HTMLButtonElement = HTML.button(
		{
			class: "iconBtnSm promptCopyPasteButton copyButton",
		},
		[
			// Copy icon:
			SVG.svg(
				{
					style: "flex-shrink: 0; pointer-events: none;",
					width: Sizing.iconMd,
					height: Sizing.iconMd,
					viewBox: "0 0 24 24",
				},
				[
					SVG.path({
						d: "M7 9.667a2.667 2.667 0 0 1 2.667 -2.667h8.666a2.667 2.667 0 0 1 2.667 2.667v8.666a2.667 2.667 0 0 1 -2.667 2.667h-8.666a2.667 2.667 0 0 1 -2.667 -2.667l0 -8.666",
						stroke: "currentColor",
						"stroke-width": "2",
						"stroke-linecap": "round",
						"stroke-linejoin": "round",
						fill: "none",
					}),
					SVG.path({
						d: "M4.012 16.737a2.005 2.005 0 0 1 -1.012 -1.737v-10c0 -1.1 .9 -2 2 -2h10c.75 0 1.158 .385 1.5 1",
						stroke: "currentColor",
						"stroke-width": "2",
						"stroke-linecap": "round",
						"stroke-linejoin": "round",
						fill: "none",
					}),
				],
			),
			"Copy",
		],
	);
	private readonly pasteButton: HTMLButtonElement = HTML.button(
		{ class: "iconBtnSm promptCopyPasteButton pasteButton" },
		[
			// Paste icon:
			SVG.svg(
				{
					style: "flex-shrink: 0; pointer-events: none;",
					width: Sizing.iconMd,
					height: Sizing.iconMd,
					viewBox: "0 0 24 24",
				},
				[
					SVG.path({
						d: "M9 5h-2a2 2 0 0 0 -2 2v12a2 2 0 0 0 2 2h3m9 -9v-5a2 2 0 0 0 -2 -2h-2",
						stroke: "currentColor",
						"stroke-width": "2",
						"stroke-linecap": "round",
						"stroke-linejoin": "round",
						fill: "none",
					}),
					SVG.path({
						d: "M13 17v-1a1 1 0 0 1 1 -1h1m3 0h1a1 1 0 0 1 1 1v1m0 3v1a1 1 0 0 1 -1 1h-1m-3 0h-1a1 1 0 0 1 -1 -1v-1",
						stroke: "currentColor",
						"stroke-width": "2",
						"stroke-linecap": "round",
						"stroke-linejoin": "round",
						fill: "none",
					}),
					SVG.path({
						d: "M9 5a2 2 0 0 1 2 -2h2a2 2 0 0 1 2 2a2 2 0 0 1 -2 2h-2a2 2 0 0 1 -2 -2",
						stroke: "currentColor",
						"stroke-width": "2",
						"stroke-linecap": "round",
						"stroke-linejoin": "round",
						fill: "none",
					}),
				],
			),
			"Paste",
		],
	);
	private readonly copyPasteContainer: HTMLDivElement = HTML.div(
		{ class: "promptCopyPasteActions" },
		this.copyButton,
		this.pasteButton,
	);
	public readonly container: HTMLDivElement = HTML.div(
		{ class: "prompt graphEditorPrompt noSelection" },
		HTML.h2("Edit Spectrum Instrument"),
		HTML.div(
			{
				style: "display: flex; width: 55%; align-self: center; flex-direction: row; align-items: center; justify-content: center;",
			},
			this._playButton,
		),
		this._drumsetButtonContainer,
		HTML.div(
			{
				style: "display: flex; flex-direction: row; align-items: center; justify-content: center; height: 80%",
			},
			this.spectrumEditor.container,
		),
		HTML.div({ class: "prompt-button-row" }, this._okayButton, this.copyPasteContainer),
		this._cancelButton,
	);

	constructor(
		private _doc: SongDocument,
		private _songEditor: PromptEditorRefs,
		private _isDrumset: boolean,
	) {
		this._okayButton.addEventListener("click", this._saveChanges);
		this._cancelButton.addEventListener("click", this._close);
		this.container.addEventListener("keydown", this.whenKeyPressed);
		this.copyButton.addEventListener("click", this._copySettings);
		this.pasteButton.addEventListener("click", this._pasteSettings);
		this._playButton.addEventListener("click", this._togglePlay);
		buildPromptTitlebar(this.container);
		this.container.addEventListener("mousemove", () => {
			this.spectrumEditor.render();
			this.spectrumEditors[this._drumsetSpectrumIndex].setSpectrumWave(
				this.spectrumEditor.getSpectrumWave().spectrum,
			);
		});
		this.container.addEventListener("mousedown", this.spectrumEditor.render);
		this.spectrumEditor.container.addEventListener("mousemove", () => {
			this.spectrumEditor.render();
			this.spectrumEditors[this._drumsetSpectrumIndex].setSpectrumWave(
				this.spectrumEditor.getSpectrumWave().spectrum,
			);
		});
		this.spectrumEditor.container.addEventListener("mousedown", this.spectrumEditor.render);
		this.updatePlayButton();
		// this.spectrumEditor.reassignDoc(_doc);

		if (this._isDrumset) {
			for (let i: number = Config.drumCount - 1; i >= 0; i--) {
				this.spectrumEditors[i] = new SpectrumEditor(
					this._doc,
					Config.drumCount - 1 - i,
					true,
				);
				this.spectrumEditors[i].setSpectrumWave(
					this._songEditor.drumsetSpectrumEditors[
						Config.drumCount - 1 - i
					].getSpectrumWave().spectrum,
				);
			}
			const colors = ColorConfig.getChannelColor(this._doc.song, this._doc.channel);
			const setDrumSpectrumForIndex = (drumIndex: number) => () => {
				this._setDrumSpectrum(drumIndex);
			};
			for (let i: number = 0; i < Config.drumCount; i++) {
				const newSpectrumButton: HTMLButtonElement = selectorButton(`${i + 1}`, {
					style: "max-width: 2em;",
				});
				this._drumsetButtons.push(newSpectrumButton);
				this._drumsetButtonContainer.appendChild(newSpectrumButton);
				newSpectrumButton.addEventListener("click", setDrumSpectrumForIndex(i));
			}
			this._drumsetButtons[Config.drumCount - 1].classList.add("last-button");
			this._drumsetButtons[0].classList.add("selected-instrument");

			this._drumsetButtonContainer.style.setProperty("--text-color-lit", colors.primaryNote);
			this._drumsetButtonContainer.style.setProperty(
				"--text-color-dim",
				colors.secondaryNote,
			);
			this._drumsetButtonContainer.style.setProperty(
				"--background-color-lit",
				colors.primaryChannel,
			);
			this._drumsetButtonContainer.style.setProperty(
				"--background-color-dim",
				colors.secondaryChannel,
			);
			this._drumsetButtonContainer.style.display = "";
			this.spectrumEditor.container.style.display = "";
			this.spectrumEditor.setSpectrumWave(
				this.spectrumEditors[this._drumsetSpectrumIndex].getSpectrumWave().spectrum,
			);
		} else {
			this._drumsetButtonContainer.style.display = "none";
			this.spectrumEditors[0] = this.spectrumEditor;
		}

		setTimeout(() => {
			this._playButton.focus();
		});
		this.spectrumEditor.render();
	}

	private _setDrumSpectrum = (index: number): void => {
		this._drumsetButtons[this._drumsetSpectrumIndex].classList.remove("selected-instrument");
		this.spectrumEditors[this._drumsetSpectrumIndex].setSpectrumWave(
			this.spectrumEditor.getSpectrumWave().spectrum,
		);

		this._drumsetSpectrumIndex = index;
		this._drumsetButtons[index].classList.add("selected-instrument");
		this.spectrumEditor.setSpectrumWave(
			this.spectrumEditors[this._drumsetSpectrumIndex].getSpectrumWave().spectrum,
		);
		this.spectrumEditor.render();
	};

	private _togglePlay = (): void => {
		this._songEditor.togglePlay();
		this.updatePlayButton();
	};

	public updatePlayButton(): void {
		updatePlayButton(this._playButton, this._doc.synth.playing);
	}

	private _saved: boolean = false;
	private _restored: boolean = false;

	public discard(): void {
		this._restoreOpeningState();
	}

	private _restoreOpeningState(): void {
		if (this._saved || this._restored) return;
		this._restored = true;
		for (const editor of this.spectrumEditors) editor.resetToInitial();
	}

	private _close = (): void => {
		this._restoreOpeningState();
		closePrompt(this._doc, this.closeCallback, this);
	};

	private _handleCommonKeys(
		event: KeyboardEvent,
		options?: {
			togglePlay?: () => void;
			undo?: () => void;
			redo?: () => void;
		},
	): void {
		if ((<Element>event.target).tagName !== "BUTTON" && event.keyCode === 13) {
			this._saveChanges();
			return;
		}
		if (event.keyCode === 27) {
			event.preventDefault();
			this._close();
			return;
		}
		if (event.keyCode === 32 && options?.togglePlay) {
			options.togglePlay();
			event.preventDefault();
			return;
		}
		if (event.keyCode === 90 && options?.undo) {
			options.undo();
			event.stopPropagation();
			return;
		}
		if (event.keyCode === 89 && options?.redo) {
			options.redo();
			event.stopPropagation();
			return;
		}
		if (event.keyCode === 219) {
			this._doc.synth.goToPrevBar();
			return;
		}
		if (event.keyCode === 221) {
			this._doc.synth.goToNextBar();
			return;
		}
		if (event.keyCode >= 49 && event.keyCode <= 57) {
			if (event.shiftKey && this._isDrumset) {
				this._setDrumSpectrum(event.keyCode - 49);
				return;
			}
		}
		if (event.keyCode === 48) {
			if (event.shiftKey && this._isDrumset) {
				this._setDrumSpectrum(9);
				return;
			}
		}
		if (event.keyCode === 189 || event.keyCode === 173) {
			if (event.shiftKey && this._isDrumset) {
				this._setDrumSpectrum(10);
				return;
			}
		}
		if (event.keyCode === 187 || event.keyCode === 61 || event.keyCode === 171) {
			if (event.shiftKey && this._isDrumset) {
				this._setDrumSpectrum(11);
				return;
			}
		}
	}

	public cleanUp = (): void => {
		this._restoreOpeningState();
		this._okayButton.removeEventListener("click", this._saveChanges);
		this._cancelButton.removeEventListener("click", this._close);
		this.container.removeEventListener("keydown", this.whenKeyPressed);
		this.spectrumEditor.container.removeEventListener("mousemove", () => {
			this.spectrumEditor.render();
		});
		this._playButton.removeEventListener("click", this._togglePlay);
	};

	private _copySettings = (): void => {
		const spectrumCopy: SpectrumWave = this.spectrumEditor.getSpectrumWave();
		window.localStorage.setItem("spectrumCopy", JSON.stringify(spectrumCopy.spectrum));
	};

	private _pasteSettings = (): void => {
		try {
			const storedSpectrumWave: number[] = JSON.parse(
				String(window.localStorage.getItem("spectrumCopy")),
			);
			this.spectrumEditor.setSpectrumWave(storedSpectrumWave);
		} catch (error) {
			console.warn("Could not paste spectrum settings.", error);
		}
	};

	public whenKeyPressed = (event: KeyboardEvent): void => {
		this._handleCommonKeys(event, {
			togglePlay: this._togglePlay,
			undo: () => {
				this.spectrumEditor.undo();
			},
			redo: () => {
				this.spectrumEditor.redo();
			},
		});
	};

	private _saveChanges = (): void => {
		this._saved = true;
		const group: ChangeGroup = new ChangeGroup();
		for (let i = 0; i < this.spectrumEditors.length; i++) {
			group.append(this.spectrumEditors[i].saveSettings());
		}
		this._doc.record(group, true);
		this._doc.prompt = null;
	};
}
